arma::cube ssm_ulg::predict_sample(const arma::mat& theta_posterior,
  const arma::mat& alpha, const unsigned int predict_type, const Rcpp::Function update_fn) {

  unsigned int d = 1;
  if (predict_type == 3) d = m;

  unsigned int n_samples = theta_posterior.n_cols;
  arma::cube sample(d, n, n_samples);

  for (unsigned int i = 0; i < n_samples; i++) {
    update_model(theta_posterior.col(i), update_fn);
    a1 = alpha.col(i);
    sample.slice(i) = sample_model(predict_type);
  }

  return sample;
}


arma::mat ssm_ulg::sample_model(const unsigned int predict_type) {

  arma::mat alpha(m, n);

  std::normal_distribution<> normal(0.0, 1.0);
  alpha.col(0) = a1;

  for (unsigned int t = 0; t < (n - 1); t++) {
    arma::vec uk(k);
    for(unsigned int j = 0; j < k; j++) {
      uk(j) = normal(engine);
    }
    alpha.col(t + 1) = C.col(t * Ctv) + 
      T.slice(t * Ttv) * alpha.col(t) + R.slice(t * Rtv) * uk;
  }

  if (predict_type < 3) {
    arma::mat y(1, n);

    for (unsigned int t = 0; t < n; t++) {
      y(0, t) = xbeta(t) + D(t * Dtv) +
        arma::as_scalar(Z.col(t * Ztv).t() * alpha.col(t));
      if(predict_type == 1)
        y(0, t) += H(t * Htv) * normal(engine);
    }

    return y;
  } else {
    return alpha;
  }

template <class ty>
RowMatrixXd
gen_table(Ref<RowMatrixXd> ori_data, vector<ty> variable_list, vector<string> df_cols) {
    int num_variables = variable_list.size();

    vector<int> which_col;
    for (auto var : variable_list) {
        int the_index = getIndex(df_cols, var.name);
        which_col.push_back(the_index);
    }

    int height = T;   // end_row - start_row + 1
    RowMatrixXd tbr = RowMatrixXd::Constant(height * N, num_variables, NAN);

#pragma omp parallel for
    for (int j = 0; j < num_variables; ++j) {
        int lag = variable_list[j].lag;
        if (lag == 0)
            tbr.col(j) = ori_data.col(which_col[j]);
        else {
#pragma omp parallel for
            for (int i = 0; i < N; ++i) {
                // int col = 0;
                Ref<RowMatrixXd> ori_i = ori_data.block(i * T, which_col[j], T, 1);
                Ref<RowMatrixXd> tbr_i = tbr.block(i * height, j, height, 1);
                tbr_i.block(0, 0, lag, 1) = RowMatrixXd::Constant(lag, 1, NAN);
                for (int k = lag; k < height; ++k) {
                    if (!isnan(ori_i(k, 0)))
                        tbr_i(k, 0) = ori_i(k - lag, 0);
                }
            }
        }
    }
    return tbr;
}

